brute_force_code:
def max_profit(nums):
    best = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            profit = nums[j] - nums[i]
            if profit > best:
                best = profit
    return best

reference_solution:
def max_profit(nums):
    best = 0
    low = nums[0]
    for x in nums:
        if x < low:
            low = x
        profit = x - low
        if profit > best:
            best = profit
    return best
